    if not data:
        return

    n = int(data[0])
    h = int(data[1])
    w = int(data[2])

    tiles = []
    idx = 3
    for i in range(n):
        a = int(data[idx]); b = int(data[idx+1]); idx += 2
        tiles.append((a, b))

    # Check total area first
    grid_area = h * w
    # Try all subsets and arrangements
    def can_cover():
        # Try all subsets of tiles (using bit masks)
        for mask in range(1, 1 << n):
            area = 0
            used_tiles = []
            for i in range(n):
                if mask & (1 << i):
                    a, b = tiles[i]
                    # Consider both orientations
                    area += a * b
                    used_tiles.append(tiles[i])

            if area != grid_area:
                continue

            # Try all permutations of used tiles
            for perm in set(permutations(used_tiles)):
                # Try to pack into h x w grid using simple backtracking
                grid = [[False] * w for _ in range(h)]

                def place_tile(tile_idx, row=0, col=0):
                    if tile_idx == len(perm):
                        return True

                    a, b = perm[tile_idx]
                    # Try both orientations
