def medianOfUniquenessArray(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    target_idx = (total_subarrays - 1) // 2  # median index (0-based, smaller if even)

    def count_subarrays_with_at_most_k_distinct(k):
        count = 0
        left = 0
        freq = {}
        for right in range(n):
            freq[nums[right]] = freq.get(nums[right], 0) + 1
            while len(freq) > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    del freq[nums[left]]
                left += 1
            count += right - left + 1
        return count

    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if count_subarrays_with_at_most_k_distinct(mid) <= target_idx:
            left = mid + 1
        else:
            right = mid
    return left
```

